package com.mamtrex.hospital.auth; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; @Service public class JwtService { private final SecretKey key; private final long ttl; public JwtService(@Value("${hospital.jwt.secret}") String secret,@Value("${hospital.jwt.ttl-minutes:60}") long ttl){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;} public String issue(UserAccount u){var now=Instant.now();return Jwts.builder().subject(u.getUsername()).claim("roles",u.getRoles().stream().map(Enum::name).toList()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(Duration.ofMinutes(ttl)))).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
